--
-- Table structure for table `du_an`
--

DROP TABLE IF EXISTS `du_an`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `du_an` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ma_danh_muc` int NOT NULL,
  `tieu_de` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `duong_dan` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mo_ta` text COLLATE utf8mb4_unicode_ci,
  `noi_dung` longtext COLLATE utf8mb4_unicode_ci,
  `gia` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gia_so` decimal(18,2) DEFAULT NULL,
  `dien_tich` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dien_tich_so` decimal(10,2) DEFAULT NULL,
  `vi_tri` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ban_do` text COLLATE utf8mb4_unicode_ci,
  `kinh_do` decimal(11,8) DEFAULT NULL,
  `vi_do` decimal(10,8) DEFAULT NULL,
  `phap_ly` enum('so_do','so_hong','giay_tay','cho_so') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `noi_that` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nam_xay_dung` year DEFAULT NULL,
  `duong_truoc_nha` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `so_tang` tinyint unsigned DEFAULT NULL,
  `loai_giao_dich` enum('ban','cho_thue','cho_thue_theo_thang','sang_nhuong') COLLATE utf8mb4_unicode_ci DEFAULT 'ban',
  `mat_tien` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `so_phong_ngu` int DEFAULT NULL,
  `so_phong_wc` int DEFAULT NULL,
  `huong_nha` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `huong_ban_cong` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `loai_bat_dong_san` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `muc_dich_giao_dich` enum('sale','rent') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chinh_chu` tinyint(1) DEFAULT '0',
  `co_the_thuong_luong` tinyint(1) NOT NULL DEFAULT '0',
  `link_video` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `link_tour_360` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `luot_xem` int DEFAULT '0',
  `luot_click_sdt` int DEFAULT '0',
  `luot_luu` int unsigned NOT NULL DEFAULT '0',
  `luot_chia_se` int unsigned NOT NULL DEFAULT '0',
  `tai_lieu_pdf` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `anh_thu_nho` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tien_ich` text COLLATE utf8mb4_unicode_ci,
  `tien_ich_json` json DEFAULT NULL,
  `trang_thai` enum('nhap','cho_duyet','xuat_ban','da_ban','tu_choi','an','khoa','xoa') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'nhap',
  `ly_do_tu_choi` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `noi_bat` tinyint(1) DEFAULT '0',
  `ngay_lam_moi` timestamp NULL DEFAULT NULL,
  `ngay_tao` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `ngay_cap_nhat` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `tinh_thanh` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tỉnh/Thành phố',
  `ten_du_an` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quan_huyen` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phuong_xa` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `goi_vip` tinyint unsigned NOT NULL DEFAULT '0',
  `ngay_het_han_vip` datetime DEFAULT NULL COMMENT 'Ngày hết hạn gói VIP',
  `ngay_het_han` datetime DEFAULT NULL,
  `ma_nguoi_dung` int DEFAULT '1' COMMENT 'Mã người dùng đăng tin',
  `tu_dong_gia_han_vip` tinyint(1) DEFAULT '0',
  `dia_chi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nguoi_lien_he` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `so_dien_thoai_lien_he` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chieu_rong` decimal(10,2) DEFAULT NULL,
  `chieu_dai` decimal(10,2) DEFAULT NULL,
  `link_360` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_title` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_description` varchar(320) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `duong_dan` (`duong_dan`),
  KEY `ma_danh_muc` (`ma_danh_muc`),
  KEY `idx_duan_public_type_date` (`trang_thai`,`muc_dich_giao_dich`,`ngay_tao`),
  KEY `idx_duan_public_category` (`trang_thai`,`ma_danh_muc`,`ngay_tao`),
  KEY `idx_duan_price` (`gia_so`),
  KEY `idx_duan_area` (`dien_tich_so`),
  KEY `idx_duan_location` (`tinh_thanh`(100),`quan_huyen`(80),`phuong_xa`(80)),
  KEY `idx_duan_vip_expiry` (`goi_vip`,`ngay_het_han_vip`),
  KEY `idx_duan_map` (`vi_do`,`kinh_do`),
  KEY `idx_du_an_trang_thai_ngay` (`trang_thai`,`ngay_tao`),
  KEY `idx_du_an_tinh_thanh` (`tinh_thanh`),
  KEY `idx_du_an_luot_xem` (`luot_xem`),
  KEY `idx_duan_user_goi_vip` (`ma_nguoi_dung`,`goi_vip`),
  KEY `idx_dashboard_user_status_created` (`ma_nguoi_dung`,`trang_thai`,`ngay_tao`),
  CONSTRAINT `fk_duan_danhmuc` FOREIGN KEY (`ma_danh_muc`) REFERENCES `danh_muc` (`id`),
  CONSTRAINT `fk_duan_nguoidung` FOREIGN KEY (`ma_nguoi_dung`) REFERENCES `nguoi_dung` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8891 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

