INSERT INTO `khach_hang` VALUES (1,1,NULL,'Nguyễn Văn Hải','hai.nguyen@gmail.com','0912345678','[ĐẶT LỊCH HẸN TƯ VẤN] Tôi muốn hẹn lịch xem thực tế dự án vào lúc 9h00 sáng Thứ Bảy tuần này.','moi',0,NULL,'Khách thích xem các căn hướng Đông Nam thoáng mát.','2026-05-22 09:12:24','2026-05-22 09:12:24'),(2,1,1,'Trần Thị Tuyết Mai','tuyetmai.bds@yahoo.com','0988776655','Cần tư vấn bảng giá chi tiết, tiến độ thanh toán và chính sách chiết khấu mới nhất.','da_lien_he',0,NULL,'Đã gọi điện lần 1, gửi bảng giá qua Zalo. Khách đang xem xét dòng tiền.','2026-05-22 09:12:24','2026-05-22 09:12:24'),(3,1,1,'Lê Hoàng Long','long.le@hoangphatgroup.vn','0909112233','[ĐẶT LỊCH HẸN TƯ VẤN] Muốn hẹn gặp trực tiếp tại văn phòng chủ đầu tư để ký phiếu đặt cọc giữ chỗ.','tiem_nang',1,'[BÁO CÁO] Đã tiếp đón khách tại văn phòng, giải đáp toàn bộ thắc mắc pháp lý. Đã chuyển hồ sơ cọc sang bộ phận kế toán.','Khách Vip, quyết định rất nhanh, có sẵn nguồn tài chính.','2026-05-22 09:12:24','2026-05-22 09:12:24'),(4,NULL,1,'Phạm Minh Đức','duc.pham@outlook.com','0933445566','Tôi muốn hỏi thủ tục vay ngân hàng tối đa bao nhiêu năm và lãi suất ưu đãi ra sao.','thanh_cong',1,'[BÁO CÁO] Đã hỗ trợ ngân hàng phê duyệt hồ sơ vay 70% giá trị hợp đồng thành công. Khách đã ký Hợp đồng mua bán.','Hỗ trợ nhiệt tình từ BIDV.','2026-05-22 09:12:24','2026-05-22 09:12:24'),(5,1,NULL,'Hoàng Ngọc Vy','vy.hoang@beautycenter.com','0977228899','Tư vấn căn hộ Studio hoặc 1 Phòng ngủ để đầu tư cho thuê.','moi',0,NULL,NULL,'2026-05-22 09:12:24','2026-05-22 09:12:24'),(6,NULL,NULL,'test20','test20@gmail.com','08994646','[ĐẶT LỊCH HẸN TƯ VẤN]\r\n- Thời gian mong muốn gọi lại: 22/6/2026 lúc 10:41\r\n- Yêu cầu cụ thể: Không có yêu cầu thêm.','moi',0,NULL,NULL,'2026-06-22 03:41:44','2026-06-22 03:41:44');
